# Build JSON array
dataset = []
start_id = 1001

for idx, (domain, text) in enumerate(sentence_templates):
    current_id = start_id + idx
    
    # Pick suitable emotion and subtype based on domain
    domain_emotions = emotions_map.get(domain, [("Neutral", "general")])
    emotion_pair = domain_emotions[idx % len(domain_emotions)]
    emotion, subtype = emotion_pair
    
    # Estimate target seconds based on word count (roughly 1.5 to 2 words per second in standard Hindi narration)
    words = text.split()
    estimated_sec = round(max(8.0, min(18.0, len(words) * 0.65 + random.choice([0.2, 0.5, 0.8, 1.1]))), 1)

    item = {
        "sentence_id": current_id,
        "block": "STD",
        "domain": domain,
        "emotion": emotion,
        "emotion_subtype": subtype,
        "target_seconds": estimated_sec,
        "sentence": text
    }
    dataset.append(item)

